/**
 * CDN Configuration
 * 
 * This module provides CDN integration for static assets.
 * Currently configured for Cloudflare R2 (S3-compatible) with fallback to local assets.
 * 
 * Setup:
 * 1. Create a Cloudflare R2 bucket
 * 2. Add R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY, R2_BUCKET_NAME, R2_ACCOUNT_ID to .env
 * 3. Optionally set CDN_URL to your custom domain
 */

export interface CDNConfig {
  enabled: boolean;
  provider: 'cloudflare-r2' | 'cloudfront' | 'local';
  baseUrl: string;
  uploadPath: string;
  region?: string;
}

export interface CDNUploadResult {
  success: boolean;
  url?: string;
  key?: string;
  error?: string;
}

export interface CDNPerformanceMetrics {
  timestamp: number;
  latency: number;
  statusCode: number;
  assetPath: string;
  cdnUrl: string;
  cached: boolean;
}

// Get CDN configuration from environment
export function getCDNConfig(): CDNConfig {
  const isEnabled = process.env.CDN_ENABLED === 'true';
  const provider = (process.env.CDN_PROVIDER as CDNConfig['provider']) || 'local';
  const customUrl = process.env.CDN_URL;

  // For Cloudflare R2, construct the public URL
  let baseUrl = '/';
  if (provider === 'cloudflare-r2' && process.env.R2_ACCOUNT_ID && process.env.R2_BUCKET_NAME) {
    baseUrl = customUrl || `https://${process.env.R2_BUCKET_NAME}.${process.env.R2_ACCOUNT_ID}.r2.cloudflarestorage.com`;
  } else if (provider === 'cloudfront' && process.env.CLOUDFRONT_URL) {
    baseUrl = process.env.CLOUDFRONT_URL;
  }

  return {
    enabled: isEnabled,
    provider,
    baseUrl,
    uploadPath: process.env.CDN_UPLOAD_PATH || '_next/static',
    region: process.env.AWS_REGION || 'auto',
  };
}

// Generate CDN URL for a static asset
export function getCDNUrl(path: string): string {
  const config = getCDNConfig();

  if (!config.enabled || config.provider === 'local') {
    return path;
  }

  // Handle different asset types
  const cleanPath = path.startsWith('/') ? path.slice(1) : path;

  return `${config.baseUrl}/${cleanPath}`;
}

// Check if asset should be served from CDN
export function isCDNEnabled(): boolean {
  return getCDNConfig().enabled;
}

// Get asset path for upload (build time)
export function getUploadPath(localPath: string): string {
  const config = getCDNConfig();

  // Map local paths to CDN paths
  if (localPath.includes('/_next/static/')) {
    return localPath.replace('./', '');
  }

  if (localPath.includes('/public/')) {
    return localPath.replace('./public/', '');
  }

  return localPath;
}

#!/usr/bin/env node

/**
 * CDN Upload Script
 * 
 * Uploads static assets to Cloudflare R2 for CDN delivery.
 * 
 * Usage:
 *   node scripts/cdn-upload.js [options]
 * 
 * Options:
 *   --dry-run    Show what would be uploaded without uploading
 *   --force      Upload all files, skip etag check
 * 
 * Environment Variables:
 *   R2_ACCESS_KEY_ID      Cloudflare R2 Access Key
 *   R2_SECRET_ACCESS_KEY  Cloudflare R2 Secret Key
 *   R2_BUCKET_NAME       R2 Bucket Name
 *   R2_ACCOUNT_ID        Cloudflare Account ID
 *   CDN_URL              Custom CDN URL (optional)
 *   CDN_ENABLED          Set to 'true' to enable CDN
 */

import { S3Client, PutObjectCommand, ListObjectsV2Command, HeadObjectCommand } from '@aws-sdk/client-s3';
import { readFileSync, readdirSync, statSync, existsSync } from 'fs';
import { join, relative } from 'path';

const DRY_RUN = process.argv.includes('--dry-run');
const FORCE = process.argv.includes('--force');

// Configuration
const config = {
  region: 'auto',
  endpoint: `https://${process.env.R2_ACCOUNT_ID}.r2.cloudflarestorage.com`,
  bucket: process.env.R2_BUCKET_NAME || 'ai-tool-navigator-assets',
  accessKeyId: process.env.R2_ACCESS_KEY_ID,
  secretAccessKey: process.env.R2_SECRET_ACCESS_KEY,
};

const DIST_DIR = join(process.cwd(), '.next');
const PUBLIC_DIR = join(process.cwd(), 'public');

// Initialize S3 client for R2
let s3Client: S3Client | null = null;

function getS3Client(): S3Client | null {
  if (!config.accessKeyId || !config.secretAccessKey) {
    console.warn('⚠️  R2 credentials not configured. CDN upload disabled.');
    console.warn('   Set R2_ACCESS_KEY_ID and R2_SECRET_ACCESS_KEY in .env');
    return null;
  }

  if (!s3Client) {
    s3Client = new S3Client({
      region: config.region,
      endpoint: config.endpoint,
      credentials: {
        accessKeyId: config.accessKeyId,
        secretAccessKey: config.secretAccessKey,
      },
    });
  }

  return s3Client;
}

// Get all files from a directory recursively
function getFiles(dir: string, baseDir: string): string[] {
  const files: string[] = [];

  if (!existsSync(dir)) {
    return files;
  }

  const items = readdirSync(dir);

  for (const item of items) {
    const fullPath = join(dir, item);
    const stat = statSync(fullPath);

    if (stat.isDirectory()) {
      files.push(...getFiles(fullPath, baseDir));
    } else {
      files.push(relative(baseDir, fullPath));
    }
  }

  return files;
}

// Check if file exists in R2 (for etag comparison)
async function fileExistsInR2(key: string): Promise<boolean> {
  const client = getS3Client();
  if (!client) return false;

  try {
    await client.send(new HeadObjectCommand({
      Bucket: config.bucket,
      Key: key,
    }));
    return true;
  } catch {
    return false;
  }
}

// Upload a single file to R2
async function uploadFile(localPath: string, key: string): Promise<{ success: boolean; error?: string }> {
  const client = getS3Client();
  if (!client) {
    return { success: false, error: 'R2 client not initialized' };
  }

  if (DRY_RUN) {
    console.log(`📤 [DRY RUN] Would upload: ${localPath} -> ${key}`);
    return { success: true };
  }

  try {
    const fileContent = readFileSync(localPath);

    // Determine content type based on file extension
    const contentType = getContentType(key);

    const command = new PutObjectCommand({
      Bucket: config.bucket,
      Key: key,
      Body: fileContent,
      ContentType: contentType,
      // Cache control for static assets
      CacheControl: getCacheControl(key),
    });

    await client.send(command);

    return { success: true };
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    return { success: false, error: message };
  }
}

// Determine content type based on file extension
function getContentType(key: string): string {
  const ext = key.split('.').pop()?.toLowerCase();

  const types: Record<string, string> = {
    html: 'text/html',
    css: 'text/css',
    js: 'application/javascript',
    mjs: 'application/javascript',
    json: 'application/json',
    png: 'image/png',
    jpg: 'image/jpeg',
    jpeg: 'image/jpeg',
    gif: 'image/gif',
    svg: 'image/svg+xml',
    webp: 'image/webp',
    ico: 'image/x-icon',
   woff: 'font/woff',
    woff2: 'font/woff2',
    ttf: 'font/ttf',
    eot: 'application/vnd.ms-fontobject',
    otf: 'font/otf',
  };

  return types[ext || ''] || 'application/octet-stream';
}

// Get cache control header based on file type
function getCacheControl(key: string): string {
  // Immutable assets (hashed) can be cached forever
  if (key.includes('._') || /\.[a-f0-9]{8,}\./.test(key)) {
    return 'public, max-age=31536000, immutable';
  }

  // Static assets
  if (key.includes('/static/')) {
    return 'public, max-age=2592000'; // 30 days
  }

  // Default
  return 'public, max-age=86400'; // 1 day
}

// Main upload function
async function main() {
  console.log('🚀 CDN Upload Script');
  console.log('=====================\n');

  if (DRY_RUN) {
    console.log('🔍 DRY RUN MODE - No files will be uploaded\n');
  }

  const client = getS3Client();
  if (!client) {
    console.log('\nℹ️  To enable CDN uploads, configure R2 credentials in .env:');
    console.log('   R2_ACCESS_KEY_ID=your_access_key');
    console.log('   R2_SECRET_ACCESS_KEY=your_secret_key');
    console.log('   R2_BUCKET_NAME=your_bucket_name');
    console.log('   R2_ACCOUNT_ID=your_account_id');
    console.log('   CDN_URL=your_custom_domain (optional)');
    return;
  }

  console.log(`📦 Target bucket: ${config.bucket}\n`);

  // Collect files to upload
  const staticFiles = getFiles(join(DIST_DIR, 'static'), DIST_DIR);
  const publicFiles = getFiles(PUBLIC_DIR, PUBLIC_DIR);

  console.log(`📁 Found ${staticFiles.length} static files in .next/static`);
  console.log(`📁 Found ${publicFiles.length} files in public/\n`);

  // Upload static files from .next/static
  let uploaded = 0;
  let skipped = 0;
  let failed = 0;

  console.log('📤 Uploading static files...');

  for (const file of staticFiles) {
    const localPath = join(DIST_DIR, 'static', file);
    const key = `_next/static/${file}`;

    // Skip if file already exists and not forcing
    if (!FORCE && await fileExistsInR2(key)) {
      skipped++;
      continue;
    }

    const result = await uploadFile(localPath, key);

    if (result.success) {
      uploaded++;
      if (!DRY_RUN) {
        console.log(`   ✅ ${key}`);
      }
    } else {
      failed++;
      console.log(`   ❌ ${key}: ${result.error}`);
    }
  }

  // Upload public files
  console.log('\n📤 Uploading public files...');

  for (const file of publicFiles) {
    const localPath = join(PUBLIC_DIR, file);
    const key = file;

    // Skip if file already exists and not forcing
    if (!FORCE && await fileExistsInR2(key)) {
      skipped++;
      continue;
    }

    const result = await uploadFile(localPath, key);

    if (result.success) {
      uploaded++;
      if (!DRY_RUN) {
        console.log(`   ✅ ${key}`);
      }
    } else {
      failed++;
      console.log(`   ❌ ${key}: ${result.error}`);
    }
  }

  // Summary
  console.log('\n📊 Summary');
  console.log('==========');
  console.log(`   ✅ Uploaded: ${uploaded}`);
  console.log(`   ⏭️  Skipped: ${skipped}`);
  console.log(`   ❌ Failed: ${failed}`);

  if (DRY_RUN) {
    console.log('\n🔍 This was a dry run. Run without --dry-run to actually upload.');
  }
}

main().catch(console.error);

/**
 * CDN Performance Monitor
 * 
 * Monitors CDN performance metrics including:
 * - Latency measurements
 * - Cache hit rates
 * - Error rates
 * 
 * Usage:
 *   import { trackCDNPerformance, getCDNMetrics } from '@/lib/cdn-monitor';
 *   
 *   // Track a CDN request
 *   await trackCDNPerformance('/_next/static/chunks/main.js', 'https://cdn.example.com/_next/static/chunks/main.js');
 *   
 *   // Get aggregated metrics
 *   const metrics = getCDNMetrics();
 */

import { getCDNConfig, type CDNPerformanceMetrics } from './cdn';

// In-memory metrics store (use Redis for production)
const metricsStore: CDNPerformanceMetrics[] = [];
const MAX_STORE_SIZE = 1000;

// Track a CDN performance metric
export async function trackCDNPerformance(
  assetPath: string,
  cdnUrl: string
): Promise<CDNPerformanceMetrics | null> {
  const config = getCDNConfig();

  if (!config.enabled) {
    return null;
  }

  const startTime = performance.now();

  try {
    const response = await fetch(cdnUrl, {
      method: 'HEAD',
      cache: 'no-store',
    });

    const latency = performance.now() - startTime;

    const metric: CDNPerformanceMetrics = {
      timestamp: Date.now(),
      latency,
      statusCode: response.status,
      assetPath,
      cdnUrl,
      cached: response.headers.get('cf-cache-status') !== null,
    };

    // Store metric
    metricsStore.push(metric);

    // Keep only recent metrics
    if (metricsStore.length > MAX_STORE_SIZE) {
      metricsStore.shift();
    }

    return metric;
  } catch (error) {
    // Track error
    const metric: CDNPerformanceMetrics = {
      timestamp: Date.now(),
      latency: performance.now() - startTime,
      statusCode: 0,
      assetPath,
      cdnUrl,
      cached: false,
    };

    metricsStore.push(metric);

    return metric;
  }
}

// Get aggregated CDN metrics
export function getCDNMetrics(): {
  totalRequests: number;
  averageLatency: number;
  cacheHitRate: number;
  errorRate: number;
  recentLatencies: number[];
} {
  if (metricsStore.length === 0) {
    return {
      totalRequests: 0,
      averageLatency: 0,
      cacheHitRate: 0,
      errorRate: 0,
      recentLatencies: [],
    };
  }

  const totalRequests = metricsStore.length;
  const successfulRequests = metricsStore.filter(m => m.statusCode > 0);
  const errorRequests = metricsStore.filter(m => m.statusCode === 0);
  const cachedRequests = metricsStore.filter(m => m.cached);

  const averageLatency = successfulRequests.reduce((sum, m) => sum + m.latency, 0) / successfulRequests.length;
  const cacheHitRate = (cachedRequests.length / totalRequests) * 100;
  const errorRate = (errorRequests.length / totalRequests) * 100;

  // Get recent latencies (last 10)
  const recentLatencies = metricsStore
    .slice(-10)
    .map(m => m.latency);

  return {
    totalRequests,
    averageLatency: Math.round(averageLatency * 100) / 100,
    cacheHitRate: Math.round(cacheHitRate * 10) / 10,
    errorRate: Math.round(errorRate * 10) / 10,
    recentLatencies: recentLatencies.map(l => Math.round(l * 100) / 100),
  };
}

// Clear metrics store
export function clearCDNMetrics(): void {
  metricsStore.length = 0;
}

// Get all stored metrics
export function getAllMetrics(): CDNPerformanceMetrics[] {
  return [...metricsStore];
}

// Middleware/utility to measure response time
export function measureCDNLatency(
  originalFetch: typeof fetch,
  cdnUrl: string
): Promise<Response> {
  const startTime = performance.now();

  return originalFetch(cdnUrl).then(response => {
    const latency = performance.now() - startTime;

    // Add timing header for debugging
    const newHeaders = new Headers(response.headers);
    newHeaders.set('x-cdn-latency', `${Math.round(latency)}ms`);

    return new Response(response.body, {
      status: response.status,
      statusText: response.statusText,
      headers: newHeaders,
    });
  });
}

import createNextIntlPlugin from 'next-intl/plugin';
import type { NextConfig } from "next";
import withPWA from "@ducanh2912/next-pwa";

const withNextIntl = createNextIntlPlugin();

/**
 * CDN Configuration
 * 
 * Configure your CDN settings in environment variables:
 * - CDN_ENABLED: Set to 'true' to enable CDN
 * - CDN_PROVIDER: 'cloudflare-r2' | 'cloudfront' | 'local' (default)
 * - CDN_URL: Your CDN base URL (e.g., https://cdn.yourdomain.com)
 * 
 * For Cloudflare R2:
 * - R2_ACCOUNT_ID: Your Cloudflare account ID
 * - R2_BUCKET_NAME: Your R2 bucket name
 * 
 * For CloudFront:
 * - CLOUDFRONT_URL: Your CloudFront distribution URL
 */

const cdnConfig = {
  enabled: process.env.CDN_ENABLED === 'true',
  baseUrl: process.env.CDN_URL || '',
  provider: process.env.CDN_PROVIDER || 'local',
};

const nextConfig: NextConfig = {
  output: "standalone",

  // Configure CDN for static files
  async headers() {
    const headers: Array<{ source: string; headers: Array<{ key: string; value: string }> }> = [];

    // Add CDN headers if enabled
    if (cdnConfig.enabled) {
      // CORS headers for CDN
      headers.push({
        source: '/:path*',
        headers: [
          { key: 'Access-Control-Allow-Origin', value: '*' },
        ],
      });

      // Cache headers for static assets
      headers.push({
        source: '/_next/static/:path*',
        headers: [
          { key: 'Cache-Control', value: 'public, max-age=31536000, immutable' },
        ],
      });

      headers.push({
        source: '/icons/:path*',
        headers: [
          { key: 'Cache-Control', value: 'public, max-age=2592000' },
        ],
      });
    }

    return headers;
  },

  // Configure asset prefix for CDN
  assetPrefix: cdnConfig.enabled ? cdnConfig.baseUrl : undefined,

  images: {
    remotePatterns: [
      {
        protocol: 'https',
        hostname: 'img.youtube.com',
      },
      {
        protocol: 'https',
        hostname: '**', // Allow all external images for flexibility
      },
    ],
    // Optionally use CDN for images
    ...(cdnConfig.enabled && cdnConfig.baseUrl ? {
      path: cdnConfig.baseUrl,
    } : {}),
  },

  // Webpack configuration for CDN
  webpack: (config, { isServer }) => {
    // Add CDN-related webpack configuration
    if (cdnConfig.enabled && !isServer) {
      // Ensure static files are properly hashed for long-term caching
      config.output.filename = '[name].[contenthash:8].js';
      config.output.chunkFilename = '[name].[contenthash:8].chunk.js';
    }
    return config;
  },
};

// PWA Configuration
const withPWAConfig = withPWA({
  dest: "public",
  disable: process.env.NODE_ENV === "development",
  register: true,
  workboxOptions: {
    skipWaiting: true,
    clientsClaim: true,
  },
});

export default withPWAConfig(withNextIntl(nextConfig));

'use client';

import { useState, useEffect } from 'react';
import { getCDNUrl, isCDNEnabled } from './cdn';

interface CDNImageProps extends React.ImgHTMLAttributes<HTMLImageElement> {
  src: string;
  fallbackSrc?: string;
  onCDNError?: () => void;
}

/**
 * CDN-aware Image component
 * 
 * Automatically uses CDN URL and falls back to original on error.
 * 
 * Usage:
 *   <CDNImage src="/images/photo.jpg" alt="Photo" />
 *   <CDNImage src="/images/photo.jpg" fallbackSrc="/images/placeholder.jpg" />
 */
export function CDNImage({
  src,
  fallbackSrc,
  onCDNError,
  ...props
}: CDNImageProps) {
  const [currentSrc, setCurrentSrc] = useState<string>(src);
  const [hasTriedFallback, setHasTriedFallback] = useState(false);
  const cdnEnabled = isCDNEnabled();

  useEffect(() => {
    // Reset state when src changes
    setHasTriedFallback(false);
    setCurrentSrc(cdnEnabled ? getCDNUrl(src) : src);
  }, [src, cdnEnabled]);

  const handleError = () => {
    if (!hasTriedFallback && fallbackSrc) {
      setCurrentSrc(fallbackSrc);
      setHasTriedFallback(true);
    } else if (!hasTriedFallback) {
      // Try original URL as fallback
      setCurrentSrc(src);
      setHasTriedFallback(true);
    } else {
      onCDNError?.();
    }
  };

  return (
    <img
      {...props}
      src={currentSrc}
      onError={handleError}
    />
  );
}

interface CDNScriptProps {
  src: string;
  strategy?: 'afterInteractive' | 'beforeInteractive' | 'lazyOnload';
  onLoad?: () => void;
  onError?: () => void;
}

/**
 * CDN-aware Script loader
 * 
 * Loads scripts from CDN with fallback to local.
 * 
 * Usage:
 *   <CDNScript src="/js/analytics.js" strategy="afterInteractive" />
 */
export function CDNScript({
  src,
  strategy = 'afterInteractive',
  onLoad,
  onError,
}: CDNScriptProps) {
  const [scriptSrc, setScriptSrc] = useState<string>('');
  const [hasTriedFallback, setHasTriedFallback] = useState(false);
  const cdnEnabled = isCDNEnabled();

  useEffect(() => {
    const url = cdnEnabled ? getCDNUrl(src) : src;
    setScriptSrc(url);
  }, [src, cdnEnabled]);

  const handleError = () => {
    if (!hasTriedFallback) {
      setScriptSrc(src); // Try original
      setHasTriedFallback(true);
    } else {
      onError?.();
    }
  };

  if (!scriptSrc) {
    return null;
  }

  return (
    <script
      src={scriptSrc}
      strategy={strategy}
      onLoad={onLoad}
      onError={handleError}
    />
  );
}

interface CDNLinkProps {
  href: string;
  as?: string;
  rel?: string;
  onLoad?: () => void;
}

/**
 * CDN-aware Link prefetcher
 * 
 * Prefetches assets from CDN for faster page loads.
 * 
 * Usage:
 *   <CDNLink href="/css/styles.css" rel="stylesheet" />
 */
export function CDNLink({ href, as, rel = 'stylesheet', onLoad }: CDNLinkProps) {
  const cdnEnabled = isCDNEnabled();

  useEffect(() => {
    if (cdnEnabled) {
      const cdnHref = getCDNUrl(href);
      // Prefetch the resource
      const link = document.createElement('link');
      link.rel = 'prefetch';
      link.as = as || (href.endsWith('.css') ? 'style' : 'script');
      link.href = cdnHref;
      document.head.appendChild(link);
    }
  }, [href, as, cdnEnabled]);

  return (
    <link
      href={cdnEnabled ? getCDNUrl(href) : href}
      rel={rel}
      as={as}
      onLoad={onLoad}
    />
  );
}

export { getCDNUrl, isCDNEnabled };

